export type College = {
  name: string;
  city: string;
  state: string;
  website: string;
  formUrl: string;
  fees: string;
  exam: string;
  courses: string[];
};

export type Course = {
  name: string;
  duration: string;
  exam: string;
};

export type Stream = {
  id: string;
  index: string;
  name: string;
  tagline: string;
  accent: string;
  category?: "med" | "non-med" | "commerce";
  courses: Course[];
  colleges: College[];
};

export const findStreamByCategory = (category: string) =>
  streams.find((s) => s.category === category);

